import { getActingAddress, subscribe } from '../app/store.js';
import { displayEthCompact } from '../app/scaling.js';
import { DGN_QUADRANTS, DGN_SYMBOLS } from '../app/dgn-traits.js';
import { readDegeneretteQuickPlay, DEGENERETTE_QUICKPLAY_CHANGED } from '../app/degenerette-quickplay.js';
import { setActionFeedback } from './action-feedback.js';

export function mountDegeneretteQuickPlay(host) {
  const summary = document.createElement('span');
  summary.className = 'site-degenerette-wager';
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'site-degenerette-quickplay';
  const feedback = document.createElement('div');
  feedback.setAttribute('role', 'status');
  feedback.hidden = true;
  document.body.append(feedback);
  host.append(summary, button);
  let busy = false;
  let displayed = null;
  const paint = () => {
    const owner = getActingAddress();
    const bet = readDegeneretteQuickPlay(owner);
    displayed = { owner, bet };
    const total = BigInt(bet.amountPerTicketWei) * BigInt(bet.ticketCount);
    const symbol = DGN_SYMBOLS[DGN_QUADRANTS[bet.symbol >> 3]][bet.symbol & 7].toUpperCase();
    const amount = bet.currency === 0
      ? `${displayEthCompact(total, 9)} ETH`
      : `${(total / (10n ** 18n)).toLocaleString('en-US')} FLIP`;
    summary.textContent = `${bet.ticketCount} CARD${bet.ticketCount === 1 ? '' : 'S'} · ${amount}`;
    button.textContent = busy ? 'BUYING…' : 'QUICK PLAY';
    button.disabled = busy || !owner;
    button.setAttribute('aria-busy', String(busy));
    button.setAttribute('aria-label', `Quick Play · ${summary.textContent} · ${symbol} · ${bet.saved ? 'repeat last manual bet' : 'default bet'}`);
    button.title = owner
      ? `${bet.saved ? 'Repeat your last confirmed manual bet' : 'Buy one card for 1,000 FLIP'} · ${symbol}. Click the logo to customize.`
      : 'Connect your wallet and select an account to play.';
    summary.title = button.title;
  };
  button.addEventListener('click', async () => {
    if (busy || !displayed?.owner) return;
    const selected = displayed;
    busy = true;
    paint();
    setActionFeedback(feedback, '');
    try {
      await import('../components/app-degenerette-panel.js');
      const panel = document.querySelector('app-degenerette-panel');
      if (!panel?.quickPlayBet) throw Error('Degenerette is still loading. Try again.');
      const result = await panel.quickPlayBet(selected.owner, selected.bet);
      setActionFeedback(feedback, result?.ok ? 'Cards purchased. Watch Pending for your reveal.' : result?.message || 'Purchase was not completed.');
    } catch (error) {
      setActionFeedback(feedback, error?.message || 'Purchase was not completed.');
    } finally {
      busy = false;
      paint();
    }
  });
  for (const field of ['connected.address', 'viewing.address', 'viewing.combined', 'ui.mode']) subscribe(field, paint);
  document.addEventListener(DEGENERETTE_QUICKPLAY_CHANGED, paint);
  window.addEventListener('storage', paint);
  paint();
}
